static FLAC__bool parse_double_(const FLAC__StreamMetadata_VorbisComment_Entry *entry, double *val)
{
        char s[32], *end;
        const char *p, *q;
        double v;

        FLAC__ASSERT(0 != entry);
        FLAC__ASSERT(0 != val);

        p = (const char *)entry->entry;
        q = strchr(p, '=');
        if(0 == q)
                return false;
        q++;
        safe_strncpy(s, q, local_min(sizeof(s), (size_t) (entry->length - (q-p))));

        v = strtod(s, &end);
        if(end == s)
                return false;

        *val = v;
        return true;
}

